/opt/venv/bin/python - <<'EOF'
import threading

class L(threading.local):
    def __init__(self, tag):
        self.tag = tag
        print("init in thread", threading.get_ident(), tag)

l = L("x")
def w():
    print(l.tag, l.count if hasattr(l,'count') else 'no count')
    l.count = 5
t = threading.Thread(target=w); t.start(); t.join()

class S(threading.local):
    def __init__(self):
        self.c = 0
        print("shard init", threading.get_ident())

class C:
    def __init__(self):
        self.shards=[]
        self.local = S()
c = C()
def w2():
    c.local.c += 1
ts=[threading.Thread(target=w2) for _ in range(3)]
[t.start() for t in ts]; [t.join() for t in ts]
print("sum", sum(s.c for s in c.shards) if False else "n/a")
EOF
